  // real photo gallery for a listing (hero first, then the rest rotated) + scene fallbacks
  let _PHOTOS=null, _STUDIO=null;
  function galleryFor(p, idx){
    if(!_PHOTOS) _PHOTOS=[PHOTO_1,PHOTO_2,PHOTO_3,PHOTO_4,PHOTO_5];
    // land: show a set of plot/context illustrations (no interiors)
    if(p && p.category==='أرض'){
      const lbls=['الموقع','حدود القطعة','المخطط المعتمد','الإطلالة'];
      return [0,1,2,3].map((k,i)=>({src:sceneData('أرض', idx+k), label:lbls[i]}));
    }
    const start=hasRealPhoto(p)?_PHOTOS.indexOf(p.photo):(idx%_PHOTOS.length);
    const s=start<0?0:start;
    const reals=[]; for(let k=0;k<_PHOTOS.length;k++) reals.push(_PHOTOS[(s+k)%_PHOTOS.length]);
    const rooms=['المجلس','غرفة النوم الرئيسية','المطبخ','دورة المياه','الإطلالة'];
    const gallery=reals.map((src,i)=>({src, label:rooms[i%rooms.length]}));
    // villa/duplex: lead with an exterior façade illustration
    if(p && (p.category==='فيلا'||p.category==='دوبلكس')){
      gallery.unshift({src:sceneData(p.category, idx), label:'الواجهة الخارجية'});
      gallery.pop();
    }
    return gallery;
  }

