    saveListing(){
      const g=id=>document.getElementById(id);
      const num=(id,d)=>{ const el=g(id); const v=parseInt(((el&&el.value)||'').replace(/[^\d]/g,''),10); return isNaN(v)?d:v; };
      const txt=(id,d)=>{ const el=g(id); return ((el&&el.value)||'').trim()||d; };
      const chk=id=>{ const el=g(id); return !!(el&&el.checked); };
      const type=txt('el_type','');
      if(!type){ showToast('⚠️ أدخل نوع العقار أولًا'); return; }
      const data={
        type, category:txt('el_cat','شقة'), neighborhood:txt('el_hood','حي الملقا'),
        area:num('el_area',150), rooms:num('el_rooms',0), bath:num('el_bath',0),
        price:num('el_price',30000), dailyRate:num('el_daily',0),
        shortTerm:chk('el_short'), available:chk('el_avail'), desc:txt('el_desc','عقار مميز في موقع حيوي.'),
      };
      data.perMeter=`${nfA(Math.round(data.price/Math.max(data.area,1)))} ر.س/م²`;
      if(state.editMode==='new'){
        const np=Object.assign({
          fair:data.price, sample:24, rating:4.7, lat:24.808+(Math.random()-.5)*0.05, lng:46.62+(Math.random()-.5)*0.05,
          cleaning:100, booked:[], estimatedValue:data.price*15, appreciation3y:8,
        }, data);
        properties.push(np);
        setState({ myListings:[...state.myListings, properties.length-1], editOpen:false });
        showToast('✅ نُشر إعلانك — 🤖 مساعد سكن هوب أرسل إشعارًا فوريًا للباحثين المطابقين في '+data.neighborhood);
      } else {
        Object.assign(properties[state.editIdx], data);
        setState({editOpen:false});
        showToast('✅ تم حفظ تعديلات الإعلان');
      }
    },
