    buyReport(){ showToast('📑 جارٍ تجهيز تقرير سكن هوب الاحترافي (٢٩ ر.س) — يصلك خلال دقائق (تجريبي)'); },
    flexRent(){ showToast('🤝 حوّلنا طلبك لشريك التمويل «إيجاري» — سيتواصل معك لإكمال التقسيط (تجريبي)'); },
