      if(k==='family'){ setState({preset:k, roomsFilter:3, activeCategory:'all'}); showToast('👨‍👩‍👧 عرض عقارات مناسبة للعائلات (٣ غرف فأكثر)'); }
      else if(k==='budget'){ setState({preset:k, priceBucket:'lt25', activeCategory:'all'}); showToast('💰 عرض الخيارات الاقتصادية (أقل من ٢٥ ألف)'); }
      else if(k==='invest'){ setState({preset:k, investorMode:true}); showToast('📈 وضع الاستثمار — يظهر العائد وتحليل الاستثمار'); }
