    publishShots(){ const n=state.captureShots.length; if(!n){ showToast('التقط أو ارفع وسائط أولًا'); return; } setState({captureOpen:false, studioOpen:false, captureShots:[]}); showToast(`🚀 تم نشر ${nfA(n)} وسائط على إعلانك (تجريبي)`); },
