    calcComm(){
      const g=id=>document.getElementById(id);
      const val=parseInt(((g('commInput')&&g('commInput').value)||'').replace(/[^\d]/g,''),10);
      if(!val||val<1000){ showToast('أدخل قيمة الصفقة بالريال'); return; }
      const rate=parseFloat((g('commRate')&&g('commRate').value)||'2.5');
      const comm=Math.round(val*rate/100), vat=Math.round(comm*0.15), net=comm; const total=comm+vat;
      setState({commResult:{val,rate,comm,vat,total}});
    },
