      const lbl=L.marker(c, {icon:L.divIcon({className:'heat-label-wrap', html:`<span class="heat-label">🔥 طلب مرتفع · +${nfA(g)}٪</span>`, iconSize:[0,0]}), interactive:false, zIndexOffset:500}).addTo(_lmap);
