      const lbl=L.marker([cyy,cx], {icon:L.divIcon({className:'land-label-wrap', html:`<span class="land-label ${pl.status}">${pl.status==='sold'?'مباع':nfA(Math.round(pl.price/1000))+'K'}</span>`, iconSize:[0,0]}), interactive:false, zIndexOffset:-100});
      lbl.addTo(_lmap);
