  /* ===== لوحة تحكم مدير التطبيق (Admin) ===== */
  function adminHtml(){
    const period=state.admPeriod||'week';
    const revAll={
      day:{ rows:[['١٢ص',2100],['٤ص',900],['٨ص',6400],['١٢م',11800],['٤م',13600],['٨م',16200]], unit:'اليوم', chg:12 },
      week:{ rows:[['السبت',38200],['الأحد',44600],['الاثنين',40100],['الثلاثاء',52400],['الأربعاء',47300],['الخميس',63000],['الجمعة',57800]], unit:'هذا الأسبوع', chg:9 },
      month:{ rows:[['الأسبوع ١',248000],['الأسبوع ٢',312000],['الأسبوع ٣',286000],['الأسبوع ٤',394600]], unit:'هذا الشهر', chg:15 },
    };
    const rev=revAll[period];
    const maxV=Math.max(...rev.rows.map(r=>r[1]));
    const totalV=rev.rows.reduce((s,r)=>s+r[1],0);
    const topV=Math.max(...rev.rows.map(r=>r[1]));
    const periods=[['day','اليوم'],['week','الأسبوع'],['month','الشهر']];
    const kpis=[
      {ic:'swap',v:'١٬٢٤٨',lbl:'عملية اليوم',chg:'▲ ٨٪',up:true,tone:'a'},
      {ic:'eye',v:'٩٬٤٢٠',lbl:'زائر اليوم',chg:'▲ ٥٪',up:true,tone:'b'},
      {ic:'activity',v:'٣٬١٨٦',lbl:'مستخدم نشط',chg:'▲ ٣٪',up:true,tone:'c'},
      {ic:'userplus',v:'٢٤٧',lbl:'مستخدم جديد',chg:'▲ ٩٪',up:true,tone:'d'},
    ];
    // mini sparkline for the hero headline, data-driven from the day series
    const admSpark=(()=>{ const pts=revAll.day.rows.map(r=>r[1]); const mn=Math.min(...pts),mx=Math.max(...pts),w=120,h=42,st=w/(pts.length-1);
      const cs=pts.map((v,i)=>[i*st, h-3-((v-mn)/((mx-mn)||1))*(h-8)]);
      const ln=cs.map((c,i)=>(i?'L':'M')+c[0].toFixed(1)+' '+c[1].toFixed(1)).join(' ');
      const ar=ln+` L${w} ${h} L0 ${h} Z`; const last=cs[cs.length-1];
      return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" fill="none" aria-hidden="true"><defs><linearGradient id="asparkg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#7CF0C4" stop-opacity=".42"/><stop offset="1" stop-color="#7CF0C4" stop-opacity="0"/></linearGradient></defs><path d="${ar}" fill="url(#asparkg)"/><path d="${ln}" stroke="#8fe6c2" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${last[0].toFixed(1)}" cy="${last[1].toFixed(1)}" r="3.2" fill="#fff"/></svg>`;
    })();
    const users=[
      {n:'فيصل الحربي',r:'مكتب عقاري',s:'نشط',j:'٢٠٢٤',av:'#B5744E'},
      {n:'نورة القحطاني',r:'باحثة عن عقار',s:'جديد',j:'اليوم',av:'#2E9E77'},
      {n:'مكتب دار العقار',r:'مكتب عقاري',s:'نشط',j:'٢٠٢٣',av:'#4C7A9C'},
      {n:'سعد الدوسري',r:'مالك عقار',s:'نشط',j:'٢٠٢٥',av:'#0E7C66'},
      {n:'خالد العتيبي',r:'باحث عن عقار',s:'موقوف',j:'٢٠٢٤',av:'#8a6d3b'},
      {n:'منيرة السالم',r:'مالكة عقار',s:'جديد',j:'اليوم',av:'#C7A252'},
    ];
    const tools=[['notify','megaphone','إشعار عام'],['report','doc','تصدير تقرير'],['perms','shield','الصلاحيات'],['settings','gear','الإعدادات'],['backup','save','نسخة احتياطية'],['log','list','سجل العمليات']];
    return `<div class="offices admin-page ${state.adminOpen?'open':''}" style="z-index:98">
      <div class="admin-hero rich">
        <div class="admin-sky">${riyadhSkylineSvg()}</div>
        <button class="icon-btn admin-close" data-act="closeAdmin">✕</button>
        <div class="admin-id">
          <div class="admin-av">${officeBadgeSvg(40)}</div>
          <div class="admin-idb">
            <div class="admin-name">لوحة تحكم المدير</div>
            <div class="admin-sub"><span class="admin-verify">صلاحية كاملة</span><span class="admin-live2"><span class="live-dot"></span> مباشر</span></div>
          </div>
        </div>
        <div class="admin-head-stat">
          <div class="ahs-l">
            <span class="ahs-lbl">${statIconSvg('wallet',13)} الدخل اليوم · ر.س</span>
            <div class="ahs-val" id="admIncome">٤٨٬٢٥٠</div>
            <span class="ahs-chg up">▲ ١٢٪ عن أمس</span>
          </div>
          <div class="ahs-spark">${admSpark}</div>
        </div>
      </div>
      <div class="admin-body">
        <div class="off-section-title tools-t">مؤشرات اليوم <span class="sec-hint">مباشر</span></div>
        <div class="adm-kpis quad">
          ${kpis.map(k=>`<div class="akpi tone-${k.tone}"><span class="akpi-ic">${statIconSvg(k.ic,17)}</span><b>${k.v}</b><small>${esc(k.lbl)}</small><span class="akpi-chg ${k.up?'up':'down'}">${k.chg}</span></div>`).join('')}
        </div>
        <div class="off-section-title">أدوات الإدارة <span class="sec-hint">وصول سريع</span></div>
        <div class="adm-tools top">
          ${tools.map(t=>`<button class="atool" data-act="admTool" data-key="${t[0]}"><span class="atool-ic">${t[1]==='shield'?shieldIconSvg(17):statIconSvg(t[1],17)}</span><span>${esc(t[2])}</span></button>`).join('')}
        </div>
        <div class="adm-insight">
          <span class="adi-ic">${statIconSvg('spark',15)}</span>
          <div class="adi-tx"><b>قراءة سكن هوب</b><span>الدخل يرتفع <em>+١٢٪</em> عن أمس، وذروة الطلب بين <em>٤–٨ مساءً</em>. أبرِز عروض حي النرجس لرفع التحويل.</span></div>
        </div>
        <div class="off-section-title">الإيرادات بالتاريخ</div>
        <div class="adm-chart">
          <div class="admc-top"><div><div class="admc-lbl">إجمالي ${esc(rev.unit)}</div><div class="admc-val">${nfA(totalV)} <small>ر.س</small></div></div><span class="admc-chg up">▲ ${nfA(rev.chg)}٪</span></div>
          <div class="admc-stats">
            <div class="admc-st"><span>متوسط ${period==='month'?'أسبوعي':'يومي'}</span><b>${nfA(Math.round(totalV/rev.rows.length))}</b><small>ر.س</small></div>
            <div class="admc-st"><span>أعلى ${period==='month'?'أسبوع':'يوم'}</span><b>${nfA(topV)}</b><small>${esc((rev.rows.find(r=>r[1]===topV)||[''])[0])}</small></div>
            <div class="admc-st gold"><span>عمولة المنصّة ٢٫٥٪</span><b>${nfA(Math.round(totalV*0.025))}</b><small>ر.س</small></div>
          </div>
          <div class="admc-rows clean">${rev.rows.map(r=>`<div class="admc-row ${r[1]===topV?'top':''}">
            <span class="acr-day">${esc(r[0])}${r[1]===topV?'<span class="acr-top">الأعلى</span>':''}</span>
            <span class="acr-val">${nfA(r[1])}<small>ر.س</small></span>
          </div>`).join('')}</div>
          <div class="admc-periods">${periods.map(p=>`<button class="admp ${period===p[0]?'on':''}" data-act="setAdmPeriod" data-key="${p[0]}">${p[1]}</button>`).join('')}</div>
        </div>
        <div class="off-section-title">إدارة المستخدمين <span class="sec-badge">${nfA(users.length)}</span></div>
        <div class="adm-users">
          ${users.map((u,i)=>{ const off=state.admUserOff[i]; const st=off?'موقوف':u.s; const cls=off?'off':(u.s==='جديد'?'new':u.s==='موقوف'?'off':'on'); return `<div class="au-row">
            <span class="au-av" style="background:${u.av}">${esc(u.n[0])}</span>
            <div class="au-b"><div class="au-top"><b>${esc(u.n)}</b><span class="au-status ${cls}">${esc(st)}</span></div><small>${esc(u.r)} · انضم ${esc(u.j)}</small></div>
            <button class="au-act ${off?'on':''}" data-act="toggleAdmUser" data-idx="${i}">${off?'تفعيل':'إيقاف'}</button>
          </div>`; }).join('')}
        </div>
        <div class="off-section-title">القوائم والترتيب <span class="sec-hint">رتّب ظهور العروض</span></div>
        <div class="adm-listings">
          ${state.admListOrder.map((pi,i)=>{ const p=properties[pi]||properties[0]; return `<div class="al-row">
            <span class="al-rank ${i===0?'gold':''}">${nfA(i+1)}</span>
            <div class="al-thumb" style="background-image:${bg(p,pi)}"></div>
            <div class="al-b"><b>${esc(p.type)}</b><small>${esc(p.neighborhood)} · ${nfA(p.price)} ر.س</small></div>
            <div class="al-move"><button data-act="admMove" data-idx="${i}" data-key="-1" ${i===0?'disabled':''}>▲</button><button data-act="admMove" data-idx="${i}" data-key="1" ${i===state.admListOrder.length-1?'disabled':''}>▼</button></div>
          </div>`; }).join('')}
        </div>
        <div class="disclaimer"><span>ⓘ</span><span>لوحة تحكم توضيحية — جميع الأرقام والمستخدمون بيانات تجريبية لأغراض العرض.</span></div>
      </div>
    </div>`;
  }

