  function editHtml(){
    const isNew=state.editMode==='new';
    const p=(!isNew && state.editIdx!=null)?properties[state.editIdx]:{};
    const val=(k,d)=>p[k]!=null?p[k]:(d!=null?d:'');
    const cats=['شقة','فيلا','دوبلكس','استوديو','أرض'];
    const hoods=[...new Set(properties.map(x=>x.neighborhood))];
    return `<div class="offices edit-page ${state.editOpen?'open':''}" style="z-index:99">
      <div class="edit-hero">
        <button class="icon-btn" data-act="closeEdit" style="background:rgba(255,255,255,.16);border-color:rgba(255,255,255,.32);color:#fff">✕</button>
        <h2>${isNew?'➕ إضافة إعلان جديد':'✏️ تعديل الإعلان'}</h2>
        <p>${isNew?'أدخل بيانات العقار لنشره في مكتبك — يظهر فورًا في التطبيق.':'حدّث بيانات العقار، والتغييرات تظهر مباشرة في الإعلان والخريطة.'}</p>
      </div>
      <div class="edit-body">
        <label class="ef">نوع العقار<input id="el_type" value="${esc(String(val('type','')))}" placeholder="مثال: شقة ٣ غرف"></label>
        <div class="ef-row">
          <label class="ef">التصنيف<select id="el_cat">${cats.map(c=>`<option ${val('category','شقة')===c?'selected':''}>${c}</option>`).join('')}</select></label>
          <label class="ef">الحي<select id="el_hood">${hoods.map(h=>`<option ${val('neighborhood',hoods[0])===h?'selected':''}>${esc(h)}</option>`).join('')}</select></label>
        </div>
        <div class="ef-row">
          <label class="ef">المساحة (م²)<input id="el_area" inputmode="numeric" value="${esc(String(val('area','')))}" placeholder="180"></label>
          <label class="ef">الإيجار السنوي (ر.س)<input id="el_price" inputmode="numeric" value="${esc(String(val('price','')))}" placeholder="38000"></label>
        </div>
        <div class="ef-row">
          <label class="ef">الغرف<input id="el_rooms" inputmode="numeric" value="${esc(String(val('rooms','')))}" placeholder="3"></label>
          <label class="ef">الحمامات<input id="el_bath" inputmode="numeric" value="${esc(String(val('bath','')))}" placeholder="2"></label>
          <label class="ef">السعر اليومي<input id="el_daily" inputmode="numeric" value="${esc(String(val('dailyRate','')))}" placeholder="260"></label>
        </div>
        <label class="ef">الوصف<textarea id="el_desc" rows="3" placeholder="اكتب وصفًا جذّابًا للعقار...">${esc(String(val('desc','')))}</textarea></label>
        <div class="ef-toggles">
          <label class="ef-check"><input id="el_avail" type="checkbox" ${val('available',true)?'checked':''}> <span>متاح الآن للإيجار</span></label>
          <label class="ef-check"><input id="el_short" type="checkbox" ${val('shortTerm',false)?'checked':''}> <span>يتاح للإيجار اليومي</span></label>
        </div>
        <div class="edit-cta">
          <button class="cta ghost" data-act="closeEdit">إلغاء</button>
          <button class="cta primary" data-act="saveListing">${isNew?'🚀 نشر الإعلان':'💾 حفظ التعديلات'}</button>
        </div>
      </div>
    </div>`;
  }

