  function savedHtml(){
    const ids = properties.map((_,i)=>i).filter(i=>state.savedIdx[i]);
    const body = ids.length
      ? ids.map(i=>{ const p=properties[i]; return `
          <div class="saved-item" data-act="openDetail" data-idx="${i}">
            <div class="thumb" style="background-image:${bg(p, i)}"></div>
            <div class="si-body">
              <div class="si-title"><span style="display:inline-flex;vertical-align:-3px">${catIconSvg(p.category)}</span> ${esc(p.type)} <span class="mm-status ${p.available?'avail':'taken'}">${p.available?'متاح':'غير متاح'}</span></div>
              <div class="si-sub">${esc(p.neighborhood)}، الرياض · ⭐ ${p.rating}</div>
              <div class="si-price">${nfA(p.price)} ر.س / سنويًا</div>
            </div>
            <button class="si-unsave" data-act="unsave" data-idx="${i}" title="إزالة">🗑️</button>
          </div>`; }).join('')
      : `<div class="saved-empty"><span class="se-ic">🤍</span><b>لا توجد عقارات محفوظة بعد</b><span>اضغط على ♡ في أي عقار، أو انقر نقرًا مزدوجًا على صورته لحفظه هنا.</span></div>`;
    return `
      <div class="sheet-overlay ${state.savedOpen?'open':''}" data-act="closeSaved"></div>
      <div class="sheet ${state.savedOpen?'open':''}">
        <div class="sheet-handle"></div>
        <div class="sheet-head"><h3>❤️ المفضلة (${ids.length})</h3><button class="close" data-act="closeSaved">✕</button></div>
        ${body}
      </div>`;
  }

